*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#a9d8d1;font-family:'DM Sans',sans-serif;color:#fff;touch-action:none}button{font:inherit;color:inherit;border:0;cursor:pointer}#game{position:relative;width:100%;height:100%;height:100dvh;overflow:hidden;background:#a9d8d1;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(26,73,71,.24),transparent 25%,transparent 58%,rgba(17,49,38,.22));z-index:1}.topbar{position:absolute;z-index:3;top:max(22px,env(safe-area-inset-top));left:clamp(20px,4vw,54px);right:clamp(20px,4vw,54px);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;color:#fff;text-shadow:0 2px 9px #29494455}.brand>div:last-child{display:flex;flex-direction:column;gap:1px}.brand b{font:700 14px 'Space Grotesk',sans-serif;letter-spacing:2px}.brand small{font-size:8px;letter-spacing:2px;opacity:.78}.brand-mark{width:32px;height:32px;position:relative;display:grid;grid-template-columns:repeat(3,1fr);align-items:end;gap:2px;padding:4px;border:1px solid #ffffff75;border-radius:10px;background:#ffffff25}.brand-mark span{background:#e8c879;border-radius:2px 2px 1px 1px}.brand-mark span:nth-child(1){height:13px}.brand-mark span:nth-child(2){height:20px;background:#fff0b0}.brand-mark span:nth-child(3){height:16px}.world-chip{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:9px 15px;border:1px solid #ffffff4d;border-radius:30px;background:#143d3560;backdrop-filter:blur(12px);font-size:9px;font-weight:700;letter-spacing:1.6px}.world-chip i{width:7px;height:7px;background:#d6e984;box-shadow:0 0 8px #d6e984;border-radius:50%}.world-chip em{font-style:normal;font-size:8px;font-weight:500;opacity:.7;padding-left:9px;border-left:1px solid #ffffff50}.icon-btn{width:36px;height:36px;display:grid;place-items:center;border:1px solid #ffffff55;border-radius:50%;background:#143d3545;backdrop-filter:blur(12px)}.sound-icon{font-size:18px}.status-card{position:absolute;z-index:2;top:88px;left:clamp(20px,4vw,54px);display:flex;align-items:center;gap:10px;padding:10px 13px;border:1px solid #fff5;border-radius:12px;background:#193e3573;backdrop-filter:blur(10px);box-shadow:0 8px 24px #244c3517}.sun-icon{font-size:20px;color:#ffe599}.status-card>div:nth-child(2){display:flex;flex-direction:column;gap:1px}.status-card b{font-size:10px}.status-card small{font-size:9px;opacity:.7}.weather-bars{display:flex;align-items:end;gap:2px;margin-left:10px;height:13px}.weather-bars i{display:block;width:2px;background:#f3e7ad;border-radius:2px}.weather-bars i:nth-child(1){height:6px}.weather-bars i:nth-child(2){height:10px}.weather-bars i:nth-child(3){height:8px}.weather-bars i:nth-child(4){height:12px}.aim{position:absolute;z-index:2;left:50%;top:48%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.85;pointer-events:none}.aim span,.aim i{position:absolute;background:#fff;border-radius:3px;box-shadow:0 1px 4px #173a3566}.aim span{height:2px;width:13px;top:8px;left:2px}.aim i{height:13px;width:2px;left:8px;top:2px}.target-label{position:absolute;z-index:2;top:calc(48% + 17px);left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:1.3px;font-weight:700;color:white;text-shadow:0 2px 5px #163c37}.hint-pill{position:absolute;z-index:2;top:calc(48% + 42px);left:50%;transform:translateX(-50%);padding:6px 10px;border:1px solid #ffffff4d;border-radius:20px;background:#173c356e;backdrop-filter:blur(8px);font-size:8px;letter-spacing:1px;white-space:nowrap;opacity:0;transition:opacity .2s}.hint-pill.show{opacity:1}.bottom-ui{position:absolute;z-index:3;bottom:max(18px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);width:min(440px,calc(100% - 32px));pointer-events:none}.inventory-title{display:flex;justify-content:space-between;padding:0 5px 7px;color:#fff;text-shadow:0 2px 5px #183e3766;font-size:8px;font-weight:700;letter-spacing:1.6px}.inventory-title span:last-child{font-weight:500;opacity:.75}.hotbar{display:flex;justify-content:center;gap:5px;padding:6px;border:1px solid #ffffff66;border-radius:14px;background:#173b3275;backdrop-filter:blur(12px);box-shadow:0 8px 25px #193e3526;pointer-events:auto}.slot{position:relative;display:grid;place-items:center;width:49px;height:48px;flex:1;max-width:54px;border:1px solid #ffffff20;border-radius:8px;background:#ffffff17;transition:transform .15s,background .15s,border .15s}.slot.selected{transform:translateY(-5px);border:1px solid #fff3b9;background:#fff3b937;box-shadow:0 0 0 2px #f6e8aa38}.block-icon{width:23px;height:23px;background:var(--block);border-radius:4px;box-shadow:inset -5px -5px 0 #0000001a,inset 2px 2px 0 #ffffff35;transform:rotate(-5deg)}.block-icon.grass{background:linear-gradient(180deg,#8ebf70 0 34%,#9b7955 34%)}.block-icon.dirt{background:#9c7951}.block-icon.stone{background:#a7aaa0}.block-icon.wood{background:linear-gradient(90deg,#9b704b 0 25%,#bd9260 25% 40%,#916742 40% 60%,#b58a59 60%)}.block-icon.leaf{background:#638e59;border-radius:7px}.slot-count{position:absolute;right:5px;bottom:2px;font-size:9px;font-weight:700;text-shadow:0 1px 3px #000}.mobile-controls{display:none}.desktop-help{position:absolute;z-index:2;right:clamp(20px,4vw,54px);bottom:33px;padding:8px 11px;border:1px solid #fff4;border-radius:9px;background:#173b326b;backdrop-filter:blur(8px);font-size:8px;letter-spacing:.5px;color:#fff}.desktop-help span{opacity:.72}.desktop-help b{padding:0 5px;opacity:.5}.toast{position:absolute;z-index:5;left:50%;top:20%;transform:translate(-50%,-10px);padding:9px 15px;border:1px solid #ffffff45;border-radius:22px;background:#173c35c9;font-size:11px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.intro,.pause-screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#16413785,#16413721 58%,#16413710);backdrop-filter:blur(2px);transition:opacity .6s,visibility .6s}.intro.hidden,.pause-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{position:absolute;left:clamp(30px,11vw,155px);top:50%;transform:translateY(-48%);width:min(370px,calc(100% - 48px));padding:0 2px;color:#fff;text-shadow:0 2px 12px #16413752}.intro-kicker{display:flex;align-items:center;gap:9px;font-size:9px;font-weight:700;letter-spacing:2px;opacity:.9}.intro-kicker span{width:19px;height:1px;background:#f3d996}.intro h1{position:relative;z-index:2;margin:13px 0 10px;font:600 clamp(46px,6.6vw,78px)/.93 'Space Grotesk',sans-serif;letter-spacing:-4px}.intro h1 em{font-style:normal;color:#f2d896}.intro p{position:relative;z-index:2;font-size:13px;line-height:1.7;opacity:.9}.play-btn{position:relative;z-index:2;margin-top:22px;display:flex;align-items:center;justify-content:space-between;gap:23px;min-width:236px;padding:14px 17px;border-radius:8px;background:#f4dfaa;color:#315b4b;font-size:10px;font-weight:800;letter-spacing:1px;box-shadow:0 8px 24px #10382a25;transition:transform .2s,background .2s}.play-btn:hover{transform:translateY(-2px);background:#fff0c8}.play-btn span{font-size:17px;font-weight:500}.intro-foot{margin-top:19px;font-size:8px;font-weight:600;letter-spacing:1.5px;opacity:.75}.intro-foot span{color:#f4dd9e;padding-right:5px}.intro-art{position:absolute;width:270px;height:180px;left:185px;top:-146px;opacity:.86;pointer-events:none}.art-sun{position:absolute;width:43px;height:43px;border-radius:50%;background:#f5dc9c;top:12px;right:40px;box-shadow:0 0 35px #f7e3ab7a}.art-hill{position:absolute;bottom:0;transform:rotate(45deg);border-radius:22px;background:#559574}.hill-back{width:140px;height:140px;left:68px;bottom:-88px;background:#64a481}.hill-front{width:160px;height:160px;left:145px;bottom:-119px;background:#3e7e65}.art-tree{position:absolute;left:130px;top:76px;width:25px;height:55px}.art-tree:before,.art-tree:after,.art-tree i{content:'';position:absolute;left:50%;transform:translateX(-50%);background:#739963;border-radius:9px}.art-tree:before{top:0;width:29px;height:28px}.art-tree:after{top:14px;width:37px;height:25px;background:#789f62}.art-tree i{top:30px;width:9px;height:25px;background:#906b4c;border-radius:2px}.art-tree b{position:absolute;z-index:1;top:16px;left:4px;width:10px;height:7px;background:#a6c078;border-radius:8px}.art-flower{position:absolute;color:#f8e2a8;font-size:16px}.flower-one{left:61px;top:105px}.flower-two{right:3px;top:112px;font-size:12px}.pause-screen{background:#173e35a6;backdrop-filter:blur(9px)}.pause-card{width:min(350px,calc(100% - 40px));padding:35px 28px;border:1px solid #ffffff45;border-radius:18px;background:#204f43ed;text-align:center;box-shadow:0 20px 70px #173b3540}.pause-symbol{display:grid;place-items:center;width:44px;height:44px;margin:0 auto 15px;border:1px solid #ffffff65;border-radius:50%;font-size:18px}.pause-card h2{margin:0;font:600 30px 'Space Grotesk',sans-serif}.pause-card p{font-size:12px;opacity:.75}.pause-card .play-btn{margin:22px auto 0}
@media(max-width:700px){.topbar{top:max(14px,env(safe-area-inset-top));left:18px;right:18px}.brand-mark{width:30px;height:30px}.world-chip{top:46px;left:auto;right:0;transform:none;padding:7px 10px;font-size:8px}.status-card{top:73px;left:18px;padding:8px 10px}.status-card small{font-size:8px}.weather-bars{display:none}.icon-btn{width:32px;height:32px}.bottom-ui{bottom:max(12px,env(safe-area-inset-bottom));width:calc(100% - 26px)}.inventory-title{padding:0 4px 5px;font-size:7px}.hotbar{gap:4px;padding:5px;border-radius:12px}.slot{height:43px;max-width:none;min-width:0;border-radius:7px}.block-icon{width:21px;height:21px}.mobile-controls{display:flex;align-items:flex-end;justify-content:space-between;position:absolute;left:0;right:0;bottom:calc(100% + 16px);pointer-events:none}.move-pad{width:106px;height:112px;position:relative;pointer-events:auto;touch-action:none}.pad-ring{position:absolute;width:90px;height:90px;left:0;bottom:5px;border:1px solid #ffffff5d;border-radius:50%;background:#183c3260;backdrop-filter:blur(6px)}.pad-ring:before,.pad-ring:after{content:'';position:absolute;background:#ffffff29}.pad-ring:before{width:1px;height:100%;left:50%}.pad-ring:after{height:1px;width:100%;top:50%}.pad-stick{position:absolute;z-index:1;left:50%;top:50%;width:36px;height:36px;transform:translate(-50%,-50%);border:1px solid #ffffff88;border-radius:50%;background:#e9dda8d9;box-shadow:0 3px 8px #183a3560}.pad-label{position:absolute;left:26px;bottom:-9px;font-size:7px;font-weight:700;letter-spacing:1px;text-shadow:0 2px 5px #183a35}.action-pad{display:flex;align-items:flex-end;gap:7px;pointer-events:auto;padding-bottom:5px}.round-action{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;width:52px;height:52px;border:1px solid #ffffff77;border-radius:50%;background:#183c3277;backdrop-filter:blur(8px);box-shadow:0 3px 10px #173b3540;touch-action:manipulation}.round-action span{font-size:21px;line-height:20px}.round-action small{font-size:6px;font-weight:700;letter-spacing:.8px}.jump-action{width:58px;height:58px;background:#eee0a1d9;color:#315b4b}.place-action{margin-bottom:20px}.mine-action{margin-bottom:0}.desktop-help{display:none}.aim{top:45%}.target-label{top:calc(45% + 18px)}.hint-pill{top:calc(45% + 43px)}.intro-card{left:clamp(27px,9vw,76px);top:48%;width:calc(100% - 52px)}.intro h1{font-size:clamp(53px,14vw,76px);letter-spacing:-3px}.intro p{font-size:12px}.intro-art{transform:scale(.75);transform-origin:bottom left;left:110px;top:-126px}.intro-kicker{font-size:8px;letter-spacing:1.5px}.play-btn{padding:14px 15px}.intro{background:linear-gradient(90deg,#164137a1,#16413756 65%,#16413732)}.target-label{font-size:7px}}
@media(max-height:650px) and (max-width:700px){.status-card{top:65px}.bottom-ui{bottom:max(7px,env(safe-area-inset-bottom))}.slot{height:37px}.mobile-controls{bottom:calc(100% + 8px)}.move-pad{height:96px}.pad-ring{width:78px;height:78px}.intro-card{top:52%}.intro-art{transform:scale(.62);top:-112px}.intro h1{font-size:53px}.intro p{margin:8px 0}.play-btn{margin-top:13px}.intro-foot{margin-top:12px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas = document.querySelector('#world');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9d8d1');
scene.fog = new THREE.Fog('#a9d8d1', 18, 54);
const camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, 0.1, 100);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.6));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

scene.add(new THREE.HemisphereLight('#e9fff7', '#687c53', 2.15));
const sun = new THREE.DirectionalLight('#fff1ce', 3.1);
sun.position.set(-12, 22, 10);
sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.left = -24; sun.shadow.camera.right = 24;
sun.shadow.camera.top = 24; sun.shadow.camera.bottom = -24;
sun.shadow.bias = -0.0004;
scene.add(sun);

const blockDefs = [
  { id: 'grass', name: 'Grass', color: '#83b86d', count: 12 },
  { id: 'dirt', name: 'Dirt', color: '#a47a51', count: 8 },
  { id: 'stone', name: 'Stone', color: '#a5aaa3', count: 5 },
  { id: 'wood', name: 'Wood', color: '#a87548', count: 4 },
  { id: 'leaf', name: 'Leaves', color: '#5d915b', count: 5 },
  { id: 'sand', name: 'Sand', color: '#dbc58d', count: 3 },
  { id: 'flower', name: 'Wildflower', color: '#e8a9a0', count: 2 },
  { id: 'moss', name: 'Moss stone', color: '#778b68', count: 0 }
];
const colors = Object.fromEntries(blockDefs.map(b => [b.id, b.color]));
const blocks = new Map();
const key = (x, y, z) => `${x},${y},${z}`;
const put = (x, y, z, type) => blocks.set(key(x, y, z), { x, y, z, type });
const get = (x, y, z) => blocks.get(key(x, y, z));

function terrainHeight(x, z) {
  const wave = Math.sin(x * 0.33 + Math.sin(z * 0.24)) * 1.35 + Math.cos(z * 0.29 - x * 0.17) * 1.05;
  const hill = Math.max(0, 3.0 - Math.hypot(x + 4, z - 2) * 0.34);
  const hill2 = Math.max(0, 1.8 - Math.hypot(x - 6, z + 5) * 0.28);
  return Math.max(1, Math.min(7, Math.floor(2.4 + wave + hill + hill2)));
}
function insideIsland(x, z) { return Math.hypot(x, z) < 15.6 + Math.sin(x * .75) * .6 + Math.cos(z * .65) * .7; }
for (let x = -18; x <= 18; x++) for (let z = -18; z <= 18; z++) {
  if (!insideIsland(x, z)) continue;
  const top = terrainHeight(x, z);
  for (let y = 0; y <= top; y++) {
    const nearRim = Math.hypot(x, z) > 13.4;
    put(x, y, z, y === top ? (nearRim && top <= 2 ? 'sand' : 'grass') : y < top - 2 ? (y === 0 ? 'stone' : 'dirt') : 'dirt');
  }
}
// Rounded voxel trees, placed on the meadow's higher ridges.
const treeSpots = [[-9,-6],[-7,7],[-2,-10],[3,8],[8,1],[10,-7],[1,-3],[-12,2],[5,-11]];
for (const [tx,tz] of treeSpots) {
  if (!insideIsland(tx,tz)) continue;
  const ground = terrainHeight(tx,tz);
  const tall = ((tx * 7 - tz * 3) & 1) ? 4 : 3;
  for (let i=1;i<=tall;i++) put(tx, ground+i, tz, 'wood');
  const crownY = ground + tall;
  for (let dy=-1;dy<=2;dy++) for (let dx=-2;dx<=2;dx++) for (let dz=-2;dz<=2;dz++) {
    const d = Math.abs(dx)+Math.abs(dz)+Math.max(0,dy-1);
    if (d < 4 && !(dx===0&&dz===0&&dy<1) && !get(tx+dx,crownY+dy,tz+dz)) put(tx+dx,crownY+dy,tz+dz,'leaf');
  }
}
// Small flower patches and warm, mossy boulders give the meadow a lived-in feel.
for (let x=-13;x<=13;x++) for (let z=-13;z<=13;z++) {
  if (!insideIsland(x,z) || get(x,terrainHeight(x,z)+1,z)) continue;
  const n = Math.sin(x*12.2+z*4.8)*Math.cos(z*8.1-x*2.7);
  if (n > .966 && Math.hypot(x,z)>4) put(x,terrainHeight(x,z)+1,z,'flower');
  if (n < -.991 && Math.hypot(x,z)>7) put(x,terrainHeight(x,z)+1,z,'moss');
}

const cube = new THREE.BoxGeometry(1,1,1);
const mat = {};
for (const d of blockDefs) {
  if (d.id === 'grass') {
    mat.grass = [new THREE.MeshStandardMaterial({color:'#a47a51',roughness:1}),new THREE.MeshStandardMaterial({color:'#a47a51',roughness:1}),new THREE.MeshStandardMaterial({color:'#88bd70',roughness:1}),new THREE.MeshStandardMaterial({color:'#91704f',roughness:1}),new THREE.MeshStandardMaterial({color:'#a47a51',roughness:1}),new THREE.MeshStandardMaterial({color:'#a47a51',roughness:1})];
  } else mat[d.id] = new THREE.MeshStandardMaterial({ color: d.color, roughness: 1 });
}
const worldGroup = new THREE.Group(); scene.add(worldGroup);
let blockMeshes = [];
function rebuildWorld() {
  for (const mesh of blockMeshes) { worldGroup.remove(mesh); mesh.dispose?.(); }
  blockMeshes = [];
  for (const d of blockDefs) {
    const list = [...blocks.values()].filter(b => b.type === d.id);
    if (!list.length) continue;
    const mesh = new THREE.InstancedMesh(cube, mat[d.id], list.length);
    mesh.userData.blocks = list;
    mesh.castShadow = d.id !== 'flower'; mesh.receiveShadow = true;
    const dummy = new THREE.Object3D();
    const tint = new THREE.Color();
    list.forEach((b,i) => {
      dummy.position.set(b.x,b.y,b.z); dummy.updateMatrix(); mesh.setMatrixAt(i,dummy.matrix);
      const variation = 0.93 + (((b.x*31+b.y*17+b.z*23)%11+11)%11)*0.012;
      tint.setScalar(variation); mesh.setColorAt(i,tint);
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    worldGroup.add(mesh); blockMeshes.push(mesh);
  }
}
rebuildWorld();

const waterGeo = new THREE.CircleGeometry(29, 48);
const waterMat = new THREE.MeshStandardMaterial({color:'#6db9b6',roughness:.34,metalness:.04,transparent:true,opacity:.9});
const water = new THREE.Mesh(waterGeo, waterMat);
water.rotation.x = -Math.PI/2; water.position.y = .12; water.receiveShadow = true; scene.add(water);
const water2 = new THREE.Mesh(new THREE.CircleGeometry(32,48), new THREE.MeshBasicMaterial({color:'#78c3bf'}));
water2.rotation.x=-Math.PI/2; water2.position.y=-.32; scene.add(water2);

const selection = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.015,1.015,1.015)), new THREE.LineBasicMaterial({color:'#fff1ad',transparent:true,opacity:.95}));
selection.visible = false; scene.add(selection);
const raycaster = new THREE.Raycaster(); raycaster.far = 6.2;
const screenCenter = new THREE.Vector2(0,0);
let target = null;

const inventory = Object.fromEntries(blockDefs.map(b=>[b.id,b.count]));
let selected = 0;
const hotbar = document.querySelector('#hotbar');
const packCount = document.querySelector('#packCount');
function drawHotbar() {
  hotbar.innerHTML = '';
  blockDefs.slice(0,7).forEach((d,i)=>{
    const slot=document.createElement('button'); slot.className=`slot${selected===i?' selected':''}`; slot.setAttribute('aria-label',`${d.name}: ${inventory[d.id]}`);
    slot.innerHTML=`<span class="block-icon ${d.id}"></span><span class="slot-count">${inventory[d.id]}</span>`;
    slot.addEventListener('pointerdown',e=>{e.preventDefault();selected=i;drawHotbar();}); hotbar.appendChild(slot);
  });
  const total=Object.values(inventory).reduce((a,b)=>a+b,0); packCount.textContent=`${total} / 99`;
}
drawHotbar();

const player = {x:0,z:0,y:terrainHeight(0,0)+.501,vy:0,grounded:true,yaw:0,pitch:-.12};
let started=false, paused=false, lastTime=performance.now(), toastTimer=0, mineCooldown=0, moveX=0,moveY=0;
const keys = {};
const toast = document.querySelector('#toast');
function showToast(text) { toast.textContent=text; toast.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>toast.classList.remove('show'),1500); }
function setView() {
  camera.position.set(player.x,player.y+1.55,player.z);
  camera.rotation.order='YXZ'; camera.rotation.y=player.yaw; camera.rotation.x=player.pitch;
}
function groundAt(x,z) {
  const ix=Math.round(x), iz=Math.round(z); let highest=-Infinity;
  for(let dx=-1;dx<=1;dx++) for(let dz=-1;dz<=1;dz++) {
    const b=get(ix+dx,0,iz+dz);
    if(Math.abs(x-(ix+dx))<.77 && Math.abs(z-(iz+dz))<.77) {
      for(let y=10;y>=0;y--) if(get(ix+dx,y,iz+dz)) { highest=Math.max(highest,y+.501); break; }
    }
  }
  return highest;
}
function updateTarget() {
  raycaster.setFromCamera(screenCenter,camera);
  const hits=raycaster.intersectObjects(blockMeshes,false);
  target=null;
  if(hits.length) {
    const hit=hits[0], b=hit.object.userData.blocks[hit.instanceId];
    if(b) target={b,normal:hit.face.normal.clone(),point:hit.point};
  }
  selection.visible=!!target;
  if(target) {
    selection.position.set(target.b.x,target.b.y,target.b.z);
    document.querySelector('#targetLabel').textContent=target.b.type.replace('-',' ').toUpperCase()+' BLOCK';
  }
}
function mineBlock() {
  if(!started||paused||!target) return;
  const b=target.b; blocks.delete(key(b.x,b.y,b.z));
  if(inventory[b.type]!==undefined) inventory[b.type]++;
  rebuildWorld(); drawHotbar(); target=null; selection.visible=false;
  showToast(`+1 ${b.type.replace('-',' ')} block`);
}
function placeBlock() {
  if(!started||paused||!target) return;
  const d=blockDefs[selected]; if(inventory[d.id]<1){showToast('No blocks left in this slot');return;}
  const n=target.normal, x=Math.round(target.b.x+n.x), y=Math.round(target.b.y+n.y), z=Math.round(target.b.z+n.z);
  if(y<0||y>12||Math.abs(x)>19||Math.abs(z)>19) return;
  if(get(x,y,z)){showToast('That spot is already taken');return;}
  if(Math.abs(x-player.x)<.8&&Math.abs(z-player.z)<.8&&y>=player.y-.3&&y<=player.y+1.7){showToast('Make a little room first');return;}
  put(x,y,z,d.id);inventory[d.id]--;rebuildWorld();drawHotbar();showToast(`${d.name} placed`);
}
function jump(){if(started&&!paused&&player.grounded){player.vy=7.1;player.grounded=false;}}
function beginGame(){started=true;document.querySelector('#intro').classList.add('hidden');lastTime=performance.now();if(innerWidth>700)canvas.requestPointerLock?.();}
document.querySelector('#playBtn').addEventListener('click',beginGame);
